import { readFileSync, writeFileSync, renameSync } from "node:fs";
import { randomUUID } from "node:crypto";

export function createStore(file) {
  let books = load();

  function load() {
    try {
      return JSON.parse(readFileSync(file, "utf8"));
    } catch {
      return [];
    }
  }

  function save() {
    const tmp = file + ".tmp";
    writeFileSync(tmp, JSON.stringify(books, null, 2));
    renameSync(tmp, file);
  }

  return {
    all() {
      return books;
    },
    get(id) {
      return books.find((b) => b.id === id);
    },
    add({ title, author, notes }) {
      const book = {
        id: randomUUID(),
        title: title.trim(),
        author: author.trim(),
        notes: (notes || "").trim(),
        finished: false,
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      save();
      return book;
    },
    finish(id) {
      const book = this.get(id);
      if (!book) return null;
      if (!book.finished) {
        book.finished = true;
        book.finishedAt = new Date().toISOString();
        save();
      }
      return book;
    },
  };
}

import { createServer } from "node:http";
import { createStore } from "./lib/store.js";

const store = createStore(new URL("./books.json", import.meta.url).pathname);

function esc(s) {
  return String(s ?? "").replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)} · My Books</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
  h1 { margin-bottom: 0.25rem; }
  a { color: #0645ad; }
  ul { padding-left: 1.25rem; }
  li { margin: 0.4rem 0; }
  form.card, .card { border: 1px solid #ddd; border-radius: 8px; padding: 1rem; margin: 1rem 0; }
  label { display: block; margin: 0.5rem 0 0.15rem; font-weight: 600; }
  input, textarea { width: 100%; box-sizing: border-box; padding: 0.4rem; }
  button { margin-top: 0.75rem; padding: 0.45rem 1rem; cursor: pointer; }
  .meta { color: #666; font-size: 0.9rem; }
  .done { color: #2a7a2a; }
  nav { margin-bottom: 1.5rem; }
</style>
</head>
<body>
<nav><a href="/">My Books</a></nav>
${body}
</body>
</html>`;
}

function bookItem(book) {
  return `<li>
    <a href="/books/${book.id}">${esc(book.title)}</a> by ${esc(book.author)}
    ${book.finished ? "" : `<form method="post" action="/books/${book.id}/finish" style="display:inline"><button>Mark finished</button></form>`}
  </li>`;
}

function homePage() {
  const books = store.all();
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  return page(
    "My Books",
    `<h1>Currently reading</h1>
    ${reading.length ? `<ul>${reading.map(bookItem).join("")}</ul>` : "<p>Nothing on the go.</p>"}
    <h1>Finished</h1>
    ${finished.length ? `<ul>${finished.map(bookItem).join("")}</ul>` : "<p>No finished books yet.</p>"}
    <h1>Add a book</h1>
    <form class="card" method="post" action="/books">
      <label for="title">Title</label>
      <input id="title" name="title" required>
      <label for="author">Author</label>
      <input id="author" name="author" required>
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" rows="3"></textarea>
      <button type="submit">Add book</button>
    </form>`,
  );
}

function bookPage(book) {
  const shareUrl = `/books/${book.id}`;
  return page(
    book.title,
    `<div class="card">
      <h1>${esc(book.title)}</h1>
      <p class="meta">by ${esc(book.author)}</p>
      <p class="meta ${book.finished ? "done" : ""}">${book.finished ? `Finished ${new Date(book.finishedAt).toLocaleDateString()}` : "Currently reading"}</p>
      ${book.finished ? "" : `<form method="post" action="/books/${book.id}/finish"><button>Mark finished</button></form>`}
      <h2>Notes</h2>
      <p>${esc(book.notes).replace(/\n/g, "<br>") || "<em>No notes yet.</em>"}</p>
      <p class="meta">Share this book: <a href="${shareUrl}">${shareUrl}</a></p>
    </div>`,
  );
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > 1e6) req.destroy();
    });
    req.on("end", () => resolve(new URLSearchParams(data)));
    req.on("error", reject);
  });
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function html(res, body, status = 200) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(body);
}

export const server = createServer(async (req, res) => {
  const url = new URL(req.url, "http://localhost");
  const bookMatch = url.pathname.match(/^\/books\/([\w-]+)$/);
  const finishMatch = url.pathname.match(/^\/books\/([\w-]+)\/finish$/);

  try {
    if (req.method === "GET" && url.pathname === "/") {
      return html(res, homePage());
    }

    if (req.method === "POST" && url.pathname === "/books") {
      const form = await readBody(req);
      const title = form.get("title") || "";
      const author = form.get("author") || "";
      if (!title.trim() || !author.trim()) {
        return html(res, page("Error", "<h1>Title and author are required.</h1>"), 400);
      }
      const book = store.add({
        title,
        author,
        notes: form.get("notes") || "",
      });
      return redirect(res, `/books/${book.id}`);
    }

    if (req.method === "GET" && bookMatch) {
      const book = store.get(bookMatch[1]);
      if (!book) return html(res, page("Not found", "<h1>Book not found.</h1>"), 404);
      return html(res, bookPage(book));
    }

    if (req.method === "POST" && finishMatch) {
      const book = store.finish(finishMatch[1]);
      if (!book) return html(res, page("Not found", "<h1>Book not found.</h1>"), 404);
      return redirect(res, `/books/${book.id}`);
    }

    html(res, page("Not found", "<h1>Page not found.</h1>"), 404);
  } catch (err) {
    console.error(err);
    html(res, page("Error", "<h1>Something went wrong.</h1>"), 500);
  }
});

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/^\//, ""))) {
  const port = process.env.PORT || 3000;
  server.listen(port, () => console.log(`Listening on http://localhost:${port}`));
}

