import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, rmSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createStore } from "../lib/store.js";

let dir, file, store;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  store = createStore(file);
});

afterEach(() => rmSync(dir, { recursive: true, force: true }));

describe("store", () => {
  it("adds a book as currently reading", () => {
    const book = store.add({ title: "Dune", author: "Frank Herbert", notes: "sand" });
    expect(book.id).toBeTruthy();
    expect(book.finished).toBe(false);
    expect(store.get(book.id).title).toBe("Dune");
  });

  it("marks a book finished", () => {
    const book = store.add({ title: "Dune", author: "Frank Herbert" });
    store.finish(book.id);
    expect(store.get(book.id).finished).toBe(true);
    expect(store.get(book.id).finishedAt).toBeTruthy();
  });

  it("persists books to the JSON file across restarts", () => {
    store.add({ title: "Dune", author: "Frank Herbert" });
    const reopened = createStore(file);
    expect(reopened.all()).toHaveLength(1);
    expect(JSON.parse(readFileSync(file, "utf8"))[0].title).toBe("Dune");
  });

  it("returns null when finishing a missing book", () => {
    expect(store.finish("nope")).toBeNull();
  });
});

